import re
from random import Random


def _parse(inp):
    tokens = inp.split()
    if not 5 <= len(tokens) <= 800003:
        return None

    values = []
    for token in tokens:
        if re.fullmatch(r"\+?[0-9]+", token) is None:
            return None
        digits = token.lstrip("+").lstrip("0")
        if not digits or len(digits) > 10:
            return None
        values.append(int(digits))

    n, width = values[:2]
    if not 1 <= n <= 200000 or not 1 <= width <= n:
        return None

    query_count_index = 2 + 2 * n
    if query_count_index >= len(values):
        return None
    q = values[query_count_index]
    if not 1 <= q <= 200000 or len(values) != query_count_index + 1 + 2 * q:
        return None

    blocks = []
    occupied = set()
    for i in range(2, query_count_index, 2):
        x, y = values[i:i + 2]
        if not 1 <= x <= width or not 1 <= y <= 10**9 or (x, y) in occupied:
            return None
        occupied.add((x, y))
        blocks.append((x, y))

    queries = []
    for i in range(query_count_index + 1, len(values), 2):
        time, block_id = values[i:i + 2]
        if not 1 <= time <= 10**9 or not 1 <= block_id <= n:
            return None
        queries.append((time, block_id))
    return width, blocks, queries


def validate_input(inp: str) -> bool:
    return _parse(inp) is not None


def _format(width, blocks, queries):
    lines = [f"{len(blocks)} {width}"]
    lines.extend(f"{x} {y}" for x, y in blocks)
    lines.append(str(len(queries)))
    lines.extend(f"{time} {block_id}" for time, block_id in queries)
    return "\n".join(lines) + "\n"


def gen_small(seed: int, n: int) -> list[str]:
    rng = Random(seed)
    cases = [
        (1, [(1, 1)], [(1, 1)]),
        (1, [(1, 10**9)], [(2, 1), (1, 1)]),
        (1, [(1, 2), (1, 1), (1, 5)],
         [(2, 1), (1, 1), (1, 2), (5, 3), (4, 3), (2, 1)]),
        (3, [(1, 1), (3, 2), (1, 3)],
         [(10**9, 1), (1, 2), (10**9, 2), (2, 3)]),
        (2, [(1, 2), (2, 2), (1, 3), (2, 3)],
         [(3, 4), (1, 1), (2, 1), (2, 3), (3, 3), (1, 4)]),
        (2, [(1, 1), (2, 1), (1, 2)],
         [(1, 1), (1, 2), (1, 3), (10**9, 3)]),
        (3, [(2, 5), (1, 1), (3, 3)],
         [(4, 2), (5, 2), (3, 3), (5, 1), (10**9, 3)]),
    ]
    result = [_format(*case) for case in cases[:max(0, n)]]

    for _ in range(len(result), n):
        count = rng.randint(1, 8)
        width = rng.randint(1, count)
        cells = [(x, y) for x in range(1, width + 1) for y in range(1, 11)]
        blocks = rng.sample(cells, count)
        queries = [(time, block_id)
                   for block_id in range(1, count + 1)
                   for time in (1, rng.randint(2, 12), 10**9)]
        queries.append(rng.choice(queries))
        rng.shuffle(queries)
        result.append(_format(width, blocks, queries))
    return result


def gen_stress(seed: int) -> list[str]:
    rng = Random(seed)
    count = 200000
    highest = 10**9
    blocks = [(1, highest - i) for i in range(count)]
    queries = []
    for block_id in range(1, count + 1):
        height = highest - block_id + 1
        time = height - rng.randrange(2)
        queries.append((time, block_id))
    queries[0] = (highest, 1)

    width = 100000
    wide_blocks = [(width, highest)]
    wide_blocks.extend((x, 1) for x in range(width - 1, 1, -1))
    wide_blocks.extend((1, y) for y in range(count - width + 1, 0, -1))
    wide_queries = [(rng.choice((1, highest - 1, highest)), block_id)
                    for block_id in range(1, count + 1)]
    wide_queries[0] = (highest - 1, 1)
    wide_queries[1] = (highest, 1)
    return [_format(1, blocks, queries), _format(width, wide_blocks, wide_queries)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    parsed = _parse(inp)
    if parsed is None:
        return [("POST-1", "Input violates the specified format or bounds.")]
    width, blocks, queries = parsed

    lines = out.split("\n")
    if lines[-1] == "":
        lines.pop()
    if len(lines) != len(queries):
        return [("POST-2", f"Expected {len(queries)} lines, got {len(lines)}.")]

    answers = [line.strip() for line in lines]
    for i, answer in enumerate(answers, 1):
        if answer not in ("Yes", "No"):
            return [("POST-2", f"Line {i} must contain one Yes or No token.")]

    empty_column = len({x for x, _ in blocks}) < width
    full_bottom = sum(y == 1 for _, y in blocks) == width
    seen = {}
    latest_yes = {}
    earliest_no = {}
    violations = []

    for i, ((time, block_id), answer) in enumerate(zip(queries, answers), 1):
        query = (time, block_id)
        if seen.setdefault(query, answer) != answer:
            violations.append(("POST-2", f"Line {i} disagrees with a repeated query."))

        _, height = blocks[block_id - 1]
        if answer == "No":
            if empty_column:
                violations.append(("POST-4", f"Line {i} reports removal with an empty column."))
            elif time < height:
                violations.append(("POST-4", f"Line {i} reports removal before the initial height."))
            earliest_no[block_id] = min(time, earliest_no.get(block_id, time))
        else:
            latest_yes[block_id] = max(time, latest_yes.get(block_id, time))

        if time == 1:
            expected = "No" if full_bottom and height == 1 else "Yes"
            if answer != expected:
                violations.append(("POST-4", f"Line {i} disagrees with the initial bottom row."))

    for block_id, time in earliest_no.items():
        if latest_yes.get(block_id, 0) >= time:
            violations.append(("POST-4", f"Block {block_id} is present at or after an absent answer."))
    return violations


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = Random(seed)
    pairs = []
    for inp in gen_small(seed, n):
        width, blocks, queries = _parse(inp)
        max_height = max(y for _, y in blocks)
        max_time = max(time for time, _ in queries)
        shift_limit = min(8, 10**9 - max_height, 10**9 - max_time)
        choices = []
        if width > 1:
            choices.append("reflect")
        if len(blocks) > 1:
            choices.append("renumber")
        if shift_limit > 0:
            choices.append("raise")
        if not choices:
            continue

        transform = rng.choice(choices)
        if transform == "reflect":
            other = _format(width, [(width + 1 - x, y) for x, y in blocks], queries)
        elif transform == "renumber":
            other = _format(width, blocks[::-1],
                            [(time, len(blocks) + 1 - block_id)
                             for time, block_id in queries])
        else:
            shift = rng.randint(1, shift_limit)
            other = _format(width, [(x, y + shift) for x, y in blocks],
                            [(time + shift, block_id) for time, block_id in queries])
        pairs.append(("POST-5", "equal", inp, other))
    return pairs


def reference_small(inp: str) -> str | None:
    parsed = _parse(inp)
    if parsed is None:
        return None
    width, blocks, queries = parsed
    if len(blocks) > 8 or len(queries) > 128:
        return None

    positions = {i: cell for i, cell in enumerate(blocks, 1)}
    answers = [""] * len(queries)
    time = 0
    stationary = False

    for index in sorted(range(len(queries)), key=lambda i: queries[i][0]):
        target, block_id = queries[index]
        while time < target and not stationary:
            if time == 256:
                return None
            time += 1
            bottom = [i for i, (_, y) in positions.items() if y == 1]
            changed = len(bottom) == width
            if changed:
                for i in bottom:
                    del positions[i]

            occupied = set(positions.values())
            for i in sorted(positions, key=lambda i: positions[i][1]):
                x, y = positions[i]
                below = (x, y - 1)
                if y > 1 and below not in occupied:
                    occupied.remove((x, y))
                    occupied.add(below)
                    positions[i] = below
                    changed = True
            stationary = not changed
        answers[index] = "Yes" if block_id in positions else "No"

    return "\n".join(answers) + "\n"
